//
// WIRED 17 August 2026, task #116, Phase C.
//
// ── READS THE COMMITTED RESULT, NOT THE PREVIEW ──────────────────────────
//
// The obvious build is to pass the refund figure through from screen 28. This
// deliberately does not: it reads booking.cancellation, which cancelStayBooking
// wrote inside the transaction.
//
// The preview and the commit can differ. cancelStayBooking recalculates rather
// than trusting the quote, so a guest who sat on the previous screen across a
// refund deadline gets a different number — and the one they must be shown is
// the one that was applied. Passing the preview forward would show them a
// figure nobody acted on.
//
// It also means this screen survives being reopened later from My Bookings,
// because the answer lives on the booking rather than in a route argument.
//
// ── WHAT IT NO LONGER CLAIMS ─────────────────────────────────────────────
//
// The Stitch version had a fixed refund, a fixed reference, and a banner
// promising "a confirmation email is on its way". No cancellation email is
// sent by anything in this product. That banner is gone rather than reworded,
// because the honest version of it would say nothing useful.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_booking.dart';
import '../models/stay_listing.dart';
import '../services/stay_booking_service.dart';
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';

class CancellationConfirmedScreen extends StatefulWidget {
  const CancellationConfirmedScreen({super.key, required this.bookingId});

  final String bookingId;

  @override
  State<CancellationConfirmedScreen> createState() =>
      _CancellationConfirmedScreenState();
}

class _CancellationConfirmedScreenState
    extends State<CancellationConfirmedScreen> {
  StayListing? _listing;
  String? _loadedFor;

  void _ensureListing(String listingId) {
    if (listingId.isEmpty || _loadedFor == listingId) return;
    _loadedFor = listingId;
    StayListingService.instance.byId(listingId).then((l) {
      if (!mounted) return;
      setState(() => _listing = l);
    }).catchError((_) => null);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.background,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        automaticallyImplyLeading: false,
        title: Text(
          'Cancelled',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.deepNavy,
          ),
        ),
      ),
      body: StreamBuilder<StayBooking?>(
        stream: StayBookingService.instance.watch(widget.bookingId),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          final StayBooking? b = snapshot.data;
          if (b == null) {
            return _message('We could not load this booking, but your '
                'cancellation was recorded. Check My bookings.');
          }

          _ensureListing(b.listingId);
          final StayCancellation? c = b.cancellation;

          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 32, 16, 32),
            children: [
              _successIndicator(),
              const SizedBox(height: 24),
              _titleAndRef(b),
              const SizedBox(height: 24),
              _propertyCard(b),
              const SizedBox(height: 16),
              if (c != null) _refundCard(b, c),
              const SizedBox(height: 24),
              _actions(),
            ],
          );
        },
      ),
    );
  }

  Widget _message(String text) => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Text(
            text,
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 15, height: 1.4, color: GoOutsColors.bodyText),
          ),
        ),
      );

  Widget _successIndicator() => Center(
        child: Container(
          width: 80,
          height: 80,
          decoration: BoxDecoration(
            color: GoOutsColors.tealSecondary.withValues(alpha: 0.12),
            shape: BoxShape.circle,
          ),
          child: const Icon(Icons.check_rounded,
              size: 42, color: GoOutsColors.tealSecondary),
        ),
      );

  Widget _titleAndRef(StayBooking b) => Column(
        children: [
          Text(
            'Your booking is cancelled',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
              fontSize: 22,
              fontWeight: FontWeight.bold,
              color: GoOutsColors.deepNavy,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'The nights have gone back on sale.',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 15, color: GoOutsColors.bodyText),
          ),
          const SizedBox(height: 10),
          // The real document id. Support and the host both search on it.
          Text(
            'Reference ${b.id}',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 12,
                color: GoOutsColors.bodyText.withValues(alpha: 0.8)),
          ),
        ],
      );

  static const List<String> _months = <String>[
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  static String _d(DateTime d) => '${d.day} ${_months[d.month - 1]}';

  Widget _propertyCard(StayBooking b) {
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(10),
            child: photos.isEmpty
                ? Container(
                    width: 64,
                    height: 64,
                    color: GoOutsColors.paleBlueTint,
                    child: const Icon(Icons.home_outlined,
                        color: GoOutsColors.primaryBlue),
                  )
                : Image.network(photos.first.url,
                    width: 64, height: 64, fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Container(
                        width: 64,
                        height: 64,
                        color: GoOutsColors.paleBlueTint)),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(_listing?.title ?? 'Your stay',
                    style: GoogleFonts.inter(
                        fontSize: 15.5,
                        fontWeight: FontWeight.bold,
                        color: GoOutsColors.deepNavy)),
                Text('${_d(b.checkIn)} to ${_d(b.checkOut)}',
                    style: GoogleFonts.inter(
                        fontSize: 13.5, color: GoOutsColors.bodyText)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _refundCard(StayBooking b, StayCancellation c) {
    final bool nothingPaid = b.paymentStatus == 'not_taken';

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text('Refund',
                  style: GoogleFonts.inter(
                      fontSize: 15,
                      fontWeight: FontWeight.bold,
                      color: GoOutsColors.deepNavy)),
              Text(c.refundAmount.formatted,
                  style: GoogleFonts.inter(
                      fontSize: 19,
                      fontWeight: FontWeight.w800,
                      color: GoOutsColors.tealSecondary)),
            ],
          ),
          if (c.explanation.isNotEmpty) ...[
            const SizedBox(height: 8),
            // The server's own words, as applied. Not the preview's.
            Text(
              c.explanation,
              style: GoogleFonts.inter(
                  fontSize: 13, height: 1.4, color: GoOutsColors.bodyText),
            ),
          ],
          // Where the money went. Refunds go back to the pot they came from,
          // so a guest who part-paid with cashback gets that part as cashback
          // — and the wallet share has already landed.
          if (!c.refundToWallet.isZero) ...[
            const SizedBox(height: 8),
            Row(
              children: [
                const Icon(Icons.account_balance_wallet_rounded,
                    size: 15, color: GoOutsColors.tealSecondary),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(
                    '${c.refundToWallet.formatted} is back in your GoOuts '
                    'wallet now.',
                    style: GoogleFonts.inter(
                        fontSize: 12.5, color: GoOutsColors.bodyText),
                  ),
                ),
              ],
            ),
          ],
          if (nothingPaid) ...[
            const SizedBox(height: 10),
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Icon(Icons.info_outline,
                    size: 15, color: GoOutsColors.bodyText),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(
                    'You were never charged for this booking, so there is '
                    'nothing to return.',
                    style: GoogleFonts.inter(
                        fontSize: 12.5, color: GoOutsColors.bodyText),
                  ),
                ),
              ],
            ),
          ],
        ],
      ),
    );
  }

  Widget _actions() => Column(
        children: [
          ElevatedButton(
            onPressed: () => Navigator.of(context).pushNamedAndRemoveUntil(
              StayRoutes.home,
              (r) => r.isFirst,
            ),
            style: ElevatedButton.styleFrom(
              backgroundColor: GoOutsColors.primaryBlue,
              minimumSize: const Size(double.infinity, 52),
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12)),
            ),
            child: Text('Find somewhere else',
                style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                    color: Colors.white)),
          ),
          const SizedBox(height: 8),
          TextButton(
            onPressed: () => Navigator.of(context)
                .pushNamedAndRemoveUntil(
                    StayRoutes.myBookings, (r) => r.isFirst),
            child: Text('My bookings',
                style: GoogleFonts.inter(
                    fontSize: 15,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.primaryBlue)),
          ),
        ],
      );
}
